        } catch (DataIntegrityViolationException e) {
            throw new RoleTakenException(sheetId, user);
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + saved.getUserName()
                + " role=" + saved.getRole().value());
        return saved;
    }
}
package net.officefloor.hq.app.role;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** Another user set the same user's role at the same moment. */
@ResponseStatus(HttpStatus.CONFLICT)
public class RoleTakenException extends RuntimeException {

    public RoleTakenException(String sheetId, String user) {
        super("The role of " + user + " on sheet " + sheetId + " was set at the same moment");
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has on a sheet. */
@Entity
@Table(name = "sheet_role")
public class SheetRole {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    /** clerk or steward. */
    @Column(name = "role", nullable = false)
    private String role;

    protected SheetRole() {
    }

    public SheetRole(String sheetId, String userName, Role role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role.value();
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public Role getRole() {
        return Role.of(role);
    }

    public void setRole(Role role) {
        this.role = role.value();
    }
}
