package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;

/**
 * Opens a selection of claims together, in list order: the people in the order they were added, each person's claims
 * newest first. Each claim is opened on its own, as its Open button would, so each gets the next number; one that
 * cannot be opened (not a DRAFT, dated in a closed period, or gone) is left as it is and counted as refused.
 */
@Service
public class BulkOpenService {

    /** How many of the selected claims were opened and how many refused. */
    public record Result(int opened, int refused) {
    }

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final ClaimService service;

    public BulkOpenService(ClaimRepository claims, PersonRepository people, ClaimService service) {
        this.claims = claims;
        this.people = people;
        this.service = service;
    }

    /** Not transactional: each claim opens in its own change, so a refused one undoes none of the others. */
    public Result open(String sheetId, String user, Collection<Long> ids) {
        Set<Long> selected = new HashSet<>(ids);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            personOrder.put(person.getId(), personOrder.size());
        }
        List<Claim> ordered = new ArrayList<>(claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> selected.contains(c.getId()))
                .toList());
        // Stable: within a person the claims stay newest first.
        ordered.sort((a, b) -> Integer.compare(personOrder.getOrDefault(a.getPersonId(), Integer.MAX_VALUE),
                personOrder.getOrDefault(b.getPersonId(), Integer.MAX_VALUE)));
        int opened = 0;
        for (Claim claim : ordered) {
            try {
                service.changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN);
                opened++;
            } catch (ClaimStatusException | ClaimActionForbiddenException | PeriodClosedException | ClaimNotFoundException
                    | PersonNotFoundException refused) {
                // Left as it is.
            }
        }
        // A selected id not on the sheet is refused too.
        return new Result(opened, selected.size() - opened);
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;

/**
 * Settles a selection of claims together, in list order: the people in the order they were added, each person's
 * claims newest first. Each claim is settled on its own, as its Settle button would, so a clerk's claim above the
 * clerk limit goes to PENDING and counts as settled; one that cannot be settled (not OPEN, opened by the same user,
 * dated in a closed period, above the proof threshold without a proof, or gone) is left as it is and counted as
 * refused.
 */
@Service
public class BulkSettleService {

    /** How many of the selected claims were settled and how many refused. */
    public record Result(int settled, int refused) {
    }

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final ClaimService service;

    public BulkSettleService(ClaimRepository claims, PersonRepository people, ClaimService service) {
        this.claims = claims;
        this.people = people;
        this.service = service;
    }

    /** Not transactional: each claim settles in its own change, so a refused one undoes none of the others. */
    public Result settle(String sheetId, String user, Collection<Long> ids) {
        Set<Long> selected = new HashSet<>(ids);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            personOrder.put(person.getId(), personOrder.size());
        }
        List<Claim> ordered = new ArrayList<>(claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> selected.contains(c.getId()))
                .toList());
        // Stable: within a person the claims stay newest first.
        ordered.sort((a, b) -> Integer.compare(personOrder.getOrDefault(a.getPersonId(), Integer.MAX_VALUE),
                personOrder.getOrDefault(b.getPersonId(), Integer.MAX_VALUE)));
        int settled = 0;
        for (Claim claim : ordered) {
            try {
                service.changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED);
                settled++;
            } catch (ClaimStatusException | ClaimActionForbiddenException | ClaimDeferException | ClaimSettledByOpenerException | ClaimProofException
                    | PeriodClosedException
                    | ClaimNotFoundException | PersonNotFoundException refused) {
                // Left as it is.
            }
        }
        // A selected id not on the sheet is refused too.
        return new Result(settled, selected.size() - settled);
    }
}
    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Map<Long, List<ClaimLog>> logs = service.logs(sheetId.trim());
        return service.list(sheetId.trim()).stream()
                .map(claim -> ClaimView.of(claim, logs.getOrDefault(claim.getId(), List.of())))
                .toList();
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.date(),
                request.note(), request.correctsValue()));
    }

    /** Add a DRAFT claim per pasted line, in order; refused as a whole when any line would be. */
    @PostMapping("/claims/paste")
    public PasteResult paste(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PasteRequest request) {
        return new PasteResult(paste.paste(sheetId.trim(), user.trim(), request.text()));
    }

    /** Edit a DRAFT claim; refused for any other status. */
    @PutMapping("/claims/{id}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.update(sheetId.trim(), user.trim(), id, request.amountValue(), request.date(),
                request.note(), request.correctsValue()));
    }

    /** Open a DRAFT claim. */
    @PostMapping("/claims/{id}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.OPEN));
    }

    /** Open the selected claims in list order; each one that cannot be opened is left as it is. */
    @PostMapping("/claims/bulk-open")
    public BulkOpenService.Result bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkOpenRequest request) {
        return bulkOpen.open(sheetId.trim(), user.trim(), request.ids());
    }

    /** Settle the selected claims in list order; each one that cannot be settled is left as it is. */
    @PostMapping("/claims/bulk-settle")
    public BulkSettleService.Result bulkSettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkSettleRequest request) {
        return bulkSettle.settle(sheetId.trim(), user.trim(), request.ids());
    }

    /** Settle an OPEN claim; refused to the user who opened it; PENDING instead when a clerk settles it above the clerk limit. */
    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.SETTLED));
    }

    /** Re-settle a SETTLED claim at its figure as of today: a steward only. */
    @PostMapping("/claims/{id}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.resettle(sheetId.trim(), user.trim(), id));
    }

    /** A steward's reason for rejecting a PENDING claim. */
    public record RejectRequest(@NotBlank @Size(max = 1000) String reason) {
    }

    public record TodayRequest(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id; an id never used before starts an empty sheet. */
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(service.load(id.trim(), user.trim()));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TodayRequest request) {
        return SheetView.of(service.setToday(id.trim(), user.trim(), request.today()));
    }
}
